import dataclasses
import datetime


@dataclasses.dataclass
class Entry:
    date: datetime.date
    category: str
    cents: int  # positive is income, negative is spending
    note: str = ""


class Ledger:
    def __init__(self):
        self.entries: list[Entry] = []

